(function () {
  /* ================= CONFIG: edit these ================= */
  const CONFIG = {
    // Replace with the user's real deposit address, generated by YOUR server/wallet provider.
    // At runtime the page also accepts localStorage "nx_deposit_address" or window.NX_DEPOSIT_ADDRESS.
    DEMO_ADDRESS: "bc1qw508d6qejxtdg4y5r3zarvary0c5xw7kv8f3t4",
    MIN_BTC: 0.0001,
    CONFIRMATIONS: 2,
    ETA: "20 – 60 minutes",
    FEE: "Free (network fee paid by sender)",
    FALLBACK_PRICE: 80564, // used only if the live price cannot be fetched
    PRICE_URL: "https://api.coinbase.com/v2/prices/BTC-USD/spot",
  };
  /* ===================================================== */

  const $ = (id) => document.getElementById(id);
  const store = {
    get(k, d) {
      try {
        const v = localStorage.getItem(k);
        return v === null ? d : JSON.parse(v);
      } catch (e) {
        return d;
      }
    },
    set(k, v) {
      try {
        localStorage.setItem(k, JSON.stringify(v));
      } catch (e) {}
    },
  };
  const esc = (s) =>
    String(s).replace(
      /[&<>"]/g,
      (c) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;" })[c],
    );
  const money = (n) =>
    "$" +
    Number(n).toLocaleString("en-US", {
      minimumFractionDigits: 2,
      maximumFractionDigits: 2,
    });
  const btcFmt = (n) =>
    Number(n).toFixed(8).replace(/0+$/, "").replace(/\.$/, ".0");

  document.documentElement.setAttribute(
    "data-theme",
    store.get("nx_theme", "light"),
  );

  const toast = (msg) => {
    const t = $("toast");
    t.textContent = msg;
    t.classList.add("show");
    clearTimeout(toast._t);
    toast._t = setTimeout(() => t.classList.remove("show"), 1800);
  };

  // ---- Address ----
  const custom =
    window.NX_DEPOSIT_ADDRESS || store.get("nx_deposit_address", null);
  const ADDRESS = custom || CONFIG.DEMO_ADDRESS;
  $("demoBanner").hidden = !!custom;
  $("addr").textContent = ADDRESS;

  // ---- Static details ----
  $("dMin").textContent = btcFmt(CONFIG.MIN_BTC) + " BTC";
  $("dConf").textContent = CONFIG.CONFIRMATIONS + " network confirmations";
  $("dEta").textContent = CONFIG.ETA;
  $("dFee").textContent = CONFIG.FEE;

  let amountBtc = 0;

  // ---- Price ----
  let price = CONFIG.FALLBACK_PRICE;
  function showPrice(live) {
    $("priceChip").textContent = (live ? "" : "~") + money(price);
    updateConv();
  }
  showPrice(false);
  function refreshPrice() {
    fetch(CONFIG.PRICE_URL)
      .then((r) => r.json())
      .then((j) => {
        const p = parseFloat(j && j.data && j.data.amount);
        if (p > 0) {
          price = p;
          showPrice(true);
        }
      })
      .catch(() => {});
  }
  refreshPrice();
  setInterval(refreshPrice, 30000);

  // ---- Amount + QR ----
  function uri() {
    return (
      "bitcoin:" +
      ADDRESS +
      (amountBtc > 0
        ? "?amount=" +
          amountBtc.toFixed(8).replace(/0+$/, "").replace(/\.$/, "")
        : "")
    );
  }
  function drawQR() {
    try {
      $("qrBox").innerHTML = NXQR.svg(uri(), { margin: 1 });
    } catch (e) {
      $("qrBox").textContent = "QR unavailable";
    }
  }
  function updateConv() {
    const raw = $("usd").value.replace(/,/g, "").trim();
    const err = $("amtErr");
    err.textContent = "";
    amountBtc = 0;
    document
      .querySelectorAll(".chip")
      .forEach((c) => c.classList.toggle("on", c.dataset.v === raw));
    if (!raw) {
      $("conv").textContent = "Enter an amount to add it to the QR code.";
    } else {
      const usd = parseFloat(raw);
      if (!/^\d*\.?\d*$/.test(raw) || !(usd > 0)) {
        err.textContent = "Enter a valid amount.";
        $("conv").textContent = "";
      } else {
        amountBtc = Math.round((usd / price) * 1e8) / 1e8;
        $("conv").innerHTML =
          "≈ <b>" +
          btcFmt(amountBtc) +
          " BTC</b> at " +
          money(price) +
          " per BTC";
        if (amountBtc < CONFIG.MIN_BTC)
          err.textContent =
            "Below the minimum deposit of " +
            btcFmt(CONFIG.MIN_BTC) +
            " BTC (about " +
            money(CONFIG.MIN_BTC * price) +
            ").";
      }
    }
    drawQR();
  }
  $("usd").addEventListener("input", updateConv);
  $("chips").addEventListener("click", (e) => {
    const c = e.target.closest(".chip");
    if (!c) return;
    $("usd").value = c.dataset.v;
    updateConv();
  });
  updateConv();

  // ---- Copy / share ----
  function copyText(text) {
    const done = () => toast("Copied");
    const fallback = () => {
      const ta = document.createElement("textarea");
      ta.value = text;
      ta.style.position = "fixed";
      ta.style.opacity = "0";
      document.body.appendChild(ta);
      ta.select();
      try {
        document.execCommand("copy");
      } catch (e) {}
      ta.remove();
      done();
    };
    if (navigator.clipboard && window.isSecureContext)
      navigator.clipboard.writeText(text).then(done, fallback);
    else fallback();
  }
  $("copyBtn").onclick = () => copyText(ADDRESS);
  $("addr").onclick = () => copyText(ADDRESS);
  $("shareBtn").onclick = () => {
    const text = "My Satwise Bitcoin deposit address:\n" + ADDRESS;
    if (navigator.share)
      navigator
        .share({ title: "Bitcoin deposit address", text })
        .catch(() => {});
    else copyText(text);
  };

  // ---- Deposit history ----
  // Demo: stored on this device. In production, load deposits from your server, which detects
  // transactions on-chain and sets the status (pending -> confirmed).
  const deposits = () => store.get("nx_deposits", []);
  function renderHistory() {
    const list = deposits();
    $("history").innerHTML = list.length
      ? list
          .map(
            (d) =>
              '<div class="list-row"><span class="coin btc">₿</span><span class="row-copy"><span class="row-title">' +
              (d.btc ? btcFmt(d.btc) + " BTC" : "Bitcoin deposit") +
              '</span><span class="row-desc dep-row-tx">' +
              (d.txid
                ? esc(d.txid.slice(0, 8)) + "…" + esc(d.txid.slice(-6)) + " · "
                : "") +
              esc(d.date) +
              '</span></span><span class="amt"><span class="tag ' +
              (d.status === "Confirmed" ? "ok" : "wait") +
              '">' +
              esc(d.status) +
              "</span></span></div>",
          )
          .join("")
      : '<p class="empty">No deposits yet.</p>';
  }
  renderHistory();

  $("sentBtn").onclick = () => {
    const tx = $("txid").value.trim();
    const err = $("txErr");
    err.textContent = "";
    if (tx && !/^[0-9a-fA-F]{64}$/.test(tx))
      return (err.textContent =
        "A Bitcoin transaction ID is 64 letters and numbers (0-9, a-f).");
    if (amountBtc > 0 && amountBtc < CONFIG.MIN_BTC)
      return (err.textContent = "Amount is below the minimum deposit.");
    if (tx && deposits().some((d) => d.txid === tx))
      return (err.textContent = "You already reported this transaction.");
    const list = deposits();
    list.unshift({
      txid: tx,
      btc: amountBtc || 0,
      status: "Pending",
      date: new Date().toLocaleDateString("en-US", {
        month: "short",
        day: "numeric",
        year: "numeric",
      }),
    });
    store.set("nx_deposits", list.slice(0, 20));
    $("txid").value = "";
    renderHistory();
    toast(
      "Thanks. We'll credit it after " +
        CONFIG.CONFIRMATIONS +
        " confirmations.",
    );
  };

  // ---- Back arrow ----
  $("backBtn").onclick = () => {
    if (history.length > 1) history.back();
    else location.href = "home.html";
  };
})();
